#!/bin/sh
# Export the strategies generated by upstream blockcheck2 modules without
# touching the firewall or network. Output format: module<TAB>arguments.

if [ "$#" -lt 2 ] || [ "$#" -gt 3 ]; then
	echo "usage: $0 ZAPRET2_DIR {http|https_tls12|https_tls13|quic} [4|6]" >&2
	exit 2
fi

ZAPRET_BASE=$1
PROTO=$2
IPV=${3:-4}
TESTDIR=$ZAPRET_BASE/blockcheck2.d/standard

if [ ! -d "$TESTDIR" ]; then
	echo "blockcheck2 strategy directory not found: $TESTDIR" >&2
	exit 1
fi

case "$IPV" in
	4) IPVV= ;;
	6) IPVV=6 ;;
	*) echo "invalid IP version: $IPV" >&2; exit 2 ;;
esac

UNAME=Linux
SCANLEVEL=force
MIN_TTL=${MIN_TTL:-1}
MAX_TTL=${MAX_TTL:-12}
MIN_AUTOTTL_DELTA=${MIN_AUTOTTL_DELTA:-1}
MAX_AUTOTTL_DELTA=${MAX_AUTOTTL_DELTA:-5}
FAKE_REPEATS=${FAKE_REPEATS:-1}
MULTIDISORDER=${MULTIDISORDER:-multidisorder}
TCP_MD5=tcp_md5
FAKE_HTTP=${FAKE_HTTP:-}
FAKE_HTTPS=${FAKE_HTTPS:-}
FAKE_QUIC=${FAKE_QUIC:-}
FAKED_PATTERN_HTTP=${FAKED_PATTERN_HTTP:-}
FAKED_PATTERN_HTTPS=${FAKED_PATTERN_HTTPS:-}
SEQOVL_PATTERN_HTTP=${SEQOVL_PATTERN_HTTP:-}
SEQOVL_PATTERN_HTTPS=${SEQOVL_PATTERN_HTTPS:-}
HOSTFAKE=${HOSTFAKE:-}

contains()
{
	case "$1" in
		*"$2"*) return 0 ;;
		*) return 1 ;;
	esac
}

extract_arg()
{
	_index=$1
	shift
	for _value in "$@"; do
		_index=$((_index - 1))
		[ "$_index" -eq 0 ] && { printf '%s\n' "$_value"; return 0; }
	done
	return 1
}

pktws_curl_test_update()
{
	shift 2
	printf '%s\t%s\n' "$CURRENT_MODULE" "$*"
	# A failed test plus SCANLEVEL=force makes upstream enumerate every branch.
	return 1
}

export_module()
(
	_module=$1
	CURRENT_MODULE=${_module##*/}
	CURRENT_MODULE=${CURRENT_MODULE%.sh}
	. "$_module"
	case "$PROTO" in
		http) command -v pktws_check_http >/dev/null && pktws_check_http : example.com ;;
		https_tls12) command -v pktws_check_https_tls12 >/dev/null && pktws_check_https_tls12 : example.com ;;
		https_tls13) command -v pktws_check_https_tls13 >/dev/null && pktws_check_https_tls13 : example.com ;;
		quic) command -v pktws_check_http3 >/dev/null && pktws_check_http3 : example.com ;;
		*) echo "invalid protocol: $PROTO" >&2; exit 2 ;;
	esac
)

case "$PROTO" in
	http|https_tls12|https_tls13|quic) ;;
	*)
		echo "invalid protocol: $PROTO" >&2
		exit 2
		;;
esac

ERROR_LOG=$(mktemp /tmp/zapret2-finder-export.XXXXXX) || exit 1
trap 'rm -f "$ERROR_LOG"' EXIT HUP INT TERM
status=0

# A separate subshell prevents functions and mutable adaptive flags from one
# module leaking into the next. The glob is intentional: a newly installed
# upstream module automatically participates in both export and parity tests.
for _module in "$TESTDIR"/*.sh; do
	[ -f "$_module" ] || continue
	: >"$ERROR_LOG"
	export_module "$_module" 2>"$ERROR_LOG"
	if [ -s "$ERROR_LOG" ]; then
		echo "cannot export blockcheck2 module: $_module" >&2
		cat "$ERROR_LOG" >&2
		status=1
	fi
done

# Probe stubs deliberately return failure so force mode walks every branch.
# Module return status is not meaningful because failed probe stubs drive force
# enumeration. Shell diagnostics are treated as errors because they can
# silently omit future upstream strategies.
exit "$status"
